import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'overrun' | 'archived';

type Project = {
  id: string;
  name: string;
  used: number;
  quota: number;
  status: ProjectStatus;
};

type StatusMeta = {
  label: string;
  tone: 'success' | 'warning' | 'danger' | 'default';
};

const STATUS_META: Record<ProjectStatus, StatusMeta> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  overrun: { label: 'Перерасход', tone: 'danger' },
  archived: { label: 'В архиве', tone: 'default' },
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'paused', 'overrun', 'archived'];

const PAGE_SIZE = 5;

const PROJECTS: Project[] = [
  { id: 'p-01', name: 'Витрина каталога', used: 72, quota: 100, status: 'active' },
  { id: 'p-02', name: 'Платёжный шлюз', used: 118, quota: 100, status: 'overrun' },
  { id: 'p-03', name: 'Мобильное приложение для курьеров', used: 44, quota: 100, status: 'active' },
  { id: 'p-04', name: 'Аналитика', used: 9, quota: 100, status: 'paused' },
  { id: 'p-05', name: '内部 CRM', used: 63, quota: 100, status: 'active' },
  { id: 'p-06', name: 'Импорт складских остатков', used: 97, quota: 100, status: 'overrun' },
  { id: 'p-07', name: 'Рассылки', used: 31, quota: 100, status: 'paused' },
  { id: 'p-08', name: 'Портал партнёров', used: 55, quota: 100, status: 'active' },
  { id: 'p-09', name: 'Legacy-биллинг', used: 12, quota: 100, status: 'archived' },
  { id: 'p-10', name: 'Поисковый индекс', used: 88, quota: 100, status: 'active' },
  { id: 'p-11', name: 'Песочница ML-экспериментов', used: 26, quota: 100, status: 'paused' },
  { id: 'p-12', name: 'Документооборот', used: 7, quota: 100, status: 'archived' },
];

export default function ProjectSpendPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status],
    );
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses([]);
    setPage(1);
  };

  const filtered = useMemo(
    () => (statuses.length === 0 ? PROJECTS : PROJECTS.filter((p) => statuses.includes(p.status))),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const visible = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
            color: 'var(--jx-text)',
          }}
        >
          Расход по проектам
        </h2>
        <p style={{ margin: 0, fontSize: '14px', color: 'var(--jx-text-2)' }}>
          Заполненность квоты за текущий месяц
        </p>
      </header>

      <div
        role="group"
        aria-label="Фильтр по статусу"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {STATUS_ORDER.map((status) => {
          const active = statuses.includes(status);
          return (
            <JxChip
              key={status}
              active={active}
              removable={active}
              onRemove={() => toggleStatus(status)}
              role="button"
              tabIndex={0}
              aria-pressed={active}
              onClick={() => toggleStatus(status)}
              onKeyDown={(event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  toggleStatus(status);
                }
              }}
              style={{ cursor: 'pointer' }}
            >
              {STATUS_META[status].label}
            </JxChip>
          );
        })}
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Под фильтры ничего не подошло"
          message="Ни один проект не совпал с выбранными статусами. Снимите фильтры, чтобы увидеть все проекты."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: '8px',
            }}
          >
            {visible.map((project) => {
              const percent = Math.round((project.used / project.quota) * 100);
              const meta = STATUS_META[project.status];
              return (
                <li
                  key={project.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '16px',
                    padding: '12px 14px',
                    background: 'var(--jx-surface-2)',
                    border: '1px solid var(--jx-border)',
                    borderRadius: 'var(--jx-r)',
                  }}
                >
                  <JxProgressCircle
                    value={project.used}
                    max={project.quota}
                    showValue
                    aria-label={`Квота проекта «${project.name}» заполнена на ${percent} процентов`}
                  />
                  <div style={{ flex: '1 1 auto', minWidth: 0 }}>
                    <div
                      style={{
                        fontSize: '15px',
                        color: 'var(--jx-text)',
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                      }}
                      title={project.name}
                    >
                      {project.name}
                    </div>
                    <div
                      style={{
                        fontSize: '13px',
                        color: 'var(--jx-text-2)',
                        fontFamily: 'var(--jx-font-mono)',
                      }}
                    >
                      {project.used} из {project.quota} ед.
                    </div>
                  </div>
                  <JxBadge tone={meta.tone} dot>
                    {meta.label}
                  </JxBadge>
                </li>
              );
            })}
          </ul>

          <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
            <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
          </div>
        </>
      )}
    </section>
  );
}

